//! Native reflected writes select the actual null-namespace content attribute.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://reflection-namespace.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn inert_reflection_namespace_id_writes_keep_namespaced_attr_and_exact_native_lookup(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createDocument('urn:original','p:Root'),source=owner.documentElement;source.setAttributeNS('urn:attribute','id','foreign');source.setAttribute('ID','upper');var foreign=source.getAttributeNodeNS('urn:attribute','id'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});source.id='A\ud800z';var a=source.getAttributeNodeNS(null,'id');if(a===null||a===foreign||source.id!=='A\ud800z'||a.value!==source.id||foreign.value!=='foreign'||source.getAttribute('ID')!=='upper'||owner.getElementById(source.id)!==source||owner.getElementById('foreign')!==null||owner.getElementById('A�z')!==null)throw 'actual null namespace id';Object.getOwnPropertyDescriptor(Element.prototype,'id').set.call(source,'B\udfffz');var records=watch.takeRecords();if(records.length!==2||records[0].attributeNamespace!==null||records[0].oldValue!==null||records[1].oldValue!=='A\ud800z'||records[1].attributeName!=='id'||records[1].target!==source||source.getAttributeNodeNS(null,'id')!==a||foreign.value!=='foreign'||a.value!=='B\udfffz')throw 'exact native id record';
"#);}
#[test]
fn inert_reflection_namespace_html_domstring_writes_keep_namespaced_metadata(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('owner'),source=owner.createElement('span');for(var name of ['title','lang','dir']){source.setAttributeNS('urn:attribute',name,'foreign');var foreign=source.getAttributeNodeNS('urn:attribute',name);source[name]='A\ud800z';var a=source.getAttributeNodeNS(null,name);if(a===null||a===foreign||a.value!=='A\ud800z'||foreign.value!=='foreign'||source[name]!==(name==='dir'?'':'A\ud800z'))throw 'null namespace HTML string reflection';source[name]='rtl';if(a.value!=='rtl'||foreign.value!=='foreign'||source[name]!=='rtl'||source.getAttributeNodeNS(null,name)!==a)throw 'native reflected Attr identity';}var copy=source.cloneNode(true);if(copy.title!=='rtl'||copy.lang!=='rtl'||copy.dir!=='rtl'||copy.getAttributeNS('urn:attribute','title')!=='foreign')throw 'independent actual clone';
"#);}
#[test]
fn inert_reflection_namespace_html_boolean_and_integer_setters_preserve_foreign_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('owner'),source=owner.createElement('span');source.setAttributeNS('urn:attribute','hidden','foreign');source.setAttributeNS('urn:attribute','tabindex','foreign');var hidden=source.getAttributeNodeNS('urn:attribute','hidden'),tab=source.getAttributeNodeNS('urn:attribute','tabindex');if(source.hidden||source.tabIndex!==-1)throw 'null namespace initial reflection';source.hidden=true;source.tabIndex=7;var nativeHidden=source.getAttributeNodeNS(null,'hidden'),nativeTab=source.getAttributeNodeNS(null,'tabindex');if(!source.hidden||source.tabIndex!==7||nativeHidden===null||nativeTab===null||hidden.value!=='foreign'||tab.value!=='foreign'||nativeTab.value!=='7')throw 'native null namespace values';source.hidden=false;source.tabIndex=-2;if(source.hidden||source.getAttributeNodeNS(null,'hidden')!==null||hidden.ownerElement!==source||hidden.value!=='foreign'||nativeHidden.ownerElement!==null||source.tabIndex!==-2||nativeTab.value!=='-2'||source.getAttributeNodeNS(null,'tabindex')!==nativeTab||tab.value!=='foreign')throw 'native removal and existing identity';
"#);}

#[test]
fn inert_reflection_namespace_no_slot_current_owner_and_conversion_reentry(){let(mut d,mut f,mut p)=fixture();let limit=p.state.node_limit;let count=d.nodes.len();p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','span');source.setAttributeNS('urn:attribute','id','foreign');var foreign=source.getAttributeNodeNS('urn:attribute','id'),calls=0,held;source.id={toString:function(){calls++;source.setAttributeNS(null,'id','effect');held=source.getAttributeNodeNS(null,'id');foreign.value='updated';return 'A\ud800z';}};if(calls!==1||source.id!=='A\ud800z'||held.value!==source.id||foreign.value!=='updated'||source.ownerDocument!==owner||source.getAttributeNodeNS(null,'id')!==held)throw 'current no-slot attributes after conversion';source.setAttributeNS('urn:attribute','title','foreign');source.title='T\udfffz';source.hidden=true;source.tabIndex=7;var copy=source.cloneNode(true);source.id='fresh';if(copy.id!=='A\ud800z'||copy.title!=='T\udfffz'||copy.getAttributeNS('urn:attribute','id')!=='updated'||copy.getAttributeNS('urn:attribute','title')!=='foreign'||!copy.hidden||copy.tabIndex!==7||copy.ownerDocument!==owner)throw 'independent no-slot native state';"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}
#[test]
fn inert_reflection_namespace_refusal_and_cancellation_leave_both_attributes_and_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('owner'),source=owner.createElement('span');for(var name of ['id','title','hidden','tabindex'])source.setAttributeNS('urn:attribute',name,'foreign');source.id='seed';source.title='title';source.hidden=true;source.tabIndex=2;var a=source.getAttributeNodeNS(null,'id'),title=source.getAttributeNodeNS(null,'title'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits,p.state.retained);let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;
for mode in 0..5{for expression in [r#"source.id='longA\ud800z';"#,r#"source.title='longB\udfffz';"#,"source.hidden=false;","source.tabIndex=7;"]{if mode==3&&!expression.contains("long"){continue;}p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=4,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits,p.state.retained),before);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}
p.begin_job();run(&mut d,&mut f,&mut p,r#"if(source.id!=='seed'||a.value!=='seed'||source.title!=='title'||title.value!=='title'||!source.hidden||source.tabIndex!==2||watch.takeRecords().length)throw 'native refusal atomicity';for(var name of ['id','title','hidden','tabindex'])if(source.getAttributeNS('urn:attribute',name)!=='foreign')throw 'foreign refusal atomicity';source.id='A\ud800z';source.title='B\udfffz';source.hidden=false;source.tabIndex=7;var records=watch.takeRecords();if(a.value!==source.id||title.value!==source.title||source.hidden||source.tabIndex!==7||records.length!==4)throw 'fresh reflection recovery';"#);}
#[test]
fn inert_reflection_namespace_saved_child_origin_precedes_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('owner'),source=owner.createElement('span');source.setAttributeNS('urn:attribute','id','foreign');source.setAttributeNS('urn:attribute','title','foreign');var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,id=Object.getOwnPropertyDescriptor(child.Element.prototype,'id'),title=Object.getOwnPropertyDescriptor(child.HTMLElement.prototype,'title'),calls=0;id.set.call(source,'seed');title.set.call(source,'title');"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-reflection-namespace.test/",&crate::navigation::Location::home()).unwrap());for expression in ["id.set.call(source,{toString:function(){calls++;return 'bad';}});","title.set.call(source,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let error=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits),before);}p.set_location(&crate::navigation::address("https://reflection-namespace.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||source.id!=='seed'||source.title!=='title'||source.getAttributeNS('urn:attribute','id')!=='foreign'||source.getAttributeNS('urn:attribute','title')!=='foreign')throw 'origin before conversion';id.set.call(source,'fresh');title.set.call(source,'recovered');if(source.id!=='fresh'||source.title!=='recovered')throw 'fresh origin recovery';");}
